<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='GET'){
 if(isset($_GET['admin'])){requireAdmin($config);$q=$pdo->query("SELECT p.id,p.slug,p.title,p.excerpt,p.author,p.status,p.published_at,p.created_at,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC");exit(json_encode(['data'=>$q->fetchAll()]));}
 $slug=$_GET['slug']??null;
 if($slug){$q=$pdo->prepare('SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status="published" LIMIT 1');$q->execute([$slug]);$post=$q->fetch();if(!$post){http_response_code(404);exit(json_encode(['error'=>'Not found.']));}$related=$pdo->prepare('SELECT p.id,p.slug,p.title,p.excerpt,p.image_url,p.author,p.published_at,c.name category_name,(SELECT COUNT(*) FROM post_likes l WHERE l.post_slug=p.slug) like_count,(SELECT COUNT(*) FROM comments m WHERE m.post_slug=p.slug AND m.status="visible") comment_count FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status="published" AND p.slug<>? AND (p.category_id=? OR p.author=?) ORDER BY (p.author=? ) DESC,p.published_at DESC LIMIT 6');$related->execute([$slug,$post['category_id'],$post['author'],$post['author']]);$post['related']=$related->fetchAll();exit(json_encode($post));}
 $limit=min(max((int)($_GET['limit']??10),1),25);$page=max((int)($_GET['page']??1),1);$offset=($page-1)*$limit;$total=(int)$pdo->query("SELECT COUNT(*) FROM posts WHERE status='published'")->fetchColumn();$q=$pdo->query("SELECT p.id,p.slug,p.title,p.excerpt,p.image_url,p.author,p.published_at,c.name category_name,(SELECT COUNT(*) FROM post_likes l WHERE l.post_slug=p.slug) like_count,(SELECT COUNT(*) FROM comments m WHERE m.post_slug=p.slug AND m.status='visible') comment_count FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published' ORDER BY p.published_at DESC,p.id DESC LIMIT $limit OFFSET $offset");$rows=$q->fetchAll();exit(json_encode(['data'=>$rows,'pagination'=>['page'=>$page,'limit'=>$limit,'total'=>$total,'has_more'=>$offset+count($rows)<$total]]));
}
requireAdmin($config);
if($_SERVER['REQUEST_METHOD']==='POST'){$d=input();foreach(['title','excerpt','content','author'] as $field){if(empty($d[$field])){http_response_code(422);exit(json_encode(['error'=>"$field is required."]));}}$slug=slugify($d['slug']??$d['title']);$cat=$pdo->prepare('SELECT id FROM categories WHERE name=? LIMIT 1');$cat->execute([$d['category']??'Technology']);$categoryId=$cat->fetchColumn()?:null;$q=$pdo->prepare('INSERT INTO posts (slug,title,excerpt,content,author,category_id,status,published_at) VALUES (?,?,?,?,?,?,"published",NOW())');try{$q->execute([$slug,trim($d['title']),trim($d['excerpt']),$d['content'],trim($d['author']),$categoryId]);$refresh=publishedContentChanged($pdo,$config,$slug);http_response_code(201);exit(json_encode(['id'=>$pdo->lastInsertId(),'slug'=>$slug]+$refresh));}catch(PDOException $e){http_response_code(409);exit(json_encode(['error'=>'That slug already exists.']));}}
if($_SERVER['REQUEST_METHOD']==='PUT'){$d=input();$id=(int)($d['id']??0);if(!$id){http_response_code(422);exit(json_encode(['error'=>'Post id required.']));}$status=in_array($d['status']??'draft',['draft','published','archived'],true)?$d['status']:'draft';$q=$pdo->prepare('UPDATE posts SET status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),published_at) WHERE id=?');$q->execute([$status,$status,$id]);$slug=(string)$pdo->query("SELECT slug FROM posts WHERE id={$id}")->fetchColumn();$refresh=publishedContentChanged($pdo,$config,$slug);exit(json_encode(['ok'=>true]+$refresh));}
if($_SERVER['REQUEST_METHOD']==='DELETE'){$id=(int)($_GET['id']??0);if(!$id){http_response_code(422);exit(json_encode(['error'=>'Post id required.']));}$q=$pdo->prepare('DELETE FROM posts WHERE id=?');$q->execute([$id]);$refresh=publishedContentChanged($pdo,$config,'deleted-'.$id);exit(json_encode(['ok'=>true]+$refresh));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
